// C11/C++11 Standard Thread-Specific Storage
_Thread_local int thread_score = 0;

void update_score(int points) {
    thread_score += points; // Local copy updated
}

// POSIX Threads (pthreads) dynamic TSD
// Used for complex types or data requiring destructors
pthread_key_t resource_key;

void cleanup_resource(void* data_ptr) {
    free(data_ptr);
}

void init_key() {
    pthread_key_create(&resource_key, cleanup_resource);
}

void* get_data() {
    return pthread_getspecific(resource_key);
}

void set_data(void* ptr) {
    pthread_setspecific(resource_key, ptr);
}
